func TestFindDupesByIssueTakesTheIssueFromTheListing(t *testing.T) {
	f := newFakeBacklog(t, []fakeIssue{
		fakeProposal(758, "Cache the session parser", "## Source\\n\\n**Origin:** entireio/cli#3001\\n", "open", ""),
