// captureStderr runs f and returns its result and what it wrote to
// os.Stderr.
func captureStderr(t *testing.T, f func() int) (int, string) {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	old := os.Stderr
	os.Stderr = w
	code := f()
	os.Stderr = old
	_ = w.Close()
	msg, _ := io.ReadAll(r)
	return code, string(msg)
}
