content.content:
func withIssue(gh github.Client, q DupesQuery, proposals []proposal) (DupesQuery, error) {
	var body string
	i := slices.IndexFunc(proposals, func(p proposal) bool { return p.Number == q.Issue })
	if i >= 0 {
		q.Title, body = proposals[i].Title, proposals[i].Body
	} else {
		is, err := gh.GetIssue(q.Repo, q.Issue)
		if err != nil {
			return q, err
		}
		q.Title, body = is.Title, is.Body
	}
	q.Sources = append(slices.Clone(q.Sources), body)
	q.Exclude = q.Issue
	return q, nil
}

